<section class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h4">Produção / Comandas</h2><form method="post" class="row g-2 mb-4"><input type="hidden" name="action" value="command"><div class="col-md-2"><input required type="number" name="command_number" class="form-control" placeholder="Comanda"></div><div class="col-md-3"><select required name="assembler_id" class="form-select"><option value="">Montador</option><?php foreach($team ?: $people as $person): if($person['role']==='Montagem'): ?><option value="<?= e($person['id']) ?>"><?= e($person['name']) ?></option><?php endif; endforeach ?></select></div><div class="col-md-1"><input name="pizzas" type="number" value="1" min="0" class="form-control"></div><div class="col-md-1"><input name="volcano_qty" type="number" value="0" min="0" class="form-control" title="Vulcão"></div><div class="col-md-1"><input name="esfiha_qty" type="number" value="0" min="0" class="form-control" title="Esfirras"></div><div class="col-md-1"><input name="sweet_qty" type="number" value="0" min="0" class="form-control" title="Doces"></div><div class="col-md-2"><select name="initial_oven" class="form-select"><option value="cozinha">Cozinha</option><option value="forno">Forno</option></select></div><div class="col-md-1"><button class="btn btn-primary w-100">OK</button></div><div class="col-12"><input name="note" class="form-control" placeholder="Observação"></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>#</th><th>Montador</th><th>Itens</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($commands as $command): ?><tr><td><?= e($command['command_number']) ?></td><td><?= e($command['assembler_name']) ?></td><td><?= e($command['pizzas']) ?> físicas · <?= e($command['volcano_qty']) ?> vulcão · <?= e($command['esfiha_qty']) ?> esfirras · <?= e($command['sweet_qty']) ?> doces</td><td><span class="badge text-bg-secondary"><?= e($command['dispatch_status'] ?: $command['status']) ?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="action" value="move"><input type="hidden" name="id" value="<?= e($command['id']) ?>"><button name="status" value="forno" class="btn btn-sm btn-outline-warning">Forno</button><button name="status" value="despacho" class="btn btn-sm btn-outline-success">Despacho</button></form></td></tr><?php endforeach ?></tbody></table></div></div></div></section>
